  B3T4: [
    question("b3t4-practice-01", "ansi-sql-y-ddl", "Que sentencia pertenece al lenguaje de definicion de datos (DDL)?", ["CREATE TABLE", "SELECT", "COMMIT", "GRANT"], 0, "CREATE TABLE define una estructura de datos, por lo que pertenece a DDL. SELECT es DML de consulta, COMMIT controla transacciones y GRANT corresponde a control de datos."),
    question("b3t4-practice-02", "ansi-sql-y-ddl", "Que clausula se usa para declarar una clave primaria al crear una tabla?", ["FOREIGN KEY", "PRIMARY KEY", "ORDER BY", "HAVING"], 1, "PRIMARY KEY identifica la clave primaria de una tabla. FOREIGN KEY declara una referencia a otra tabla, mientras que ORDER BY y HAVING son clausulas de consulta."),
    question("b3t4-practice-03", "dml-dcl-y-consultas", "Que instruccion confirma de forma explicita una transaccion?", ["ROLLBACK", "SAVEPOINT", "COMMIT", "REVOKE"], 2, "COMMIT hace persistentes los cambios de la transaccion. ROLLBACK los deshace, SAVEPOINT establece un punto parcial y REVOKE retira privilegios."),
    question("b3t4-practice-04", "dml-dcl-y-consultas", "La clausula WHERE en una consulta SELECT sirve para:", ["Ordenar el resultado", "Filtrar filas antes de la agrupacion", "Limitar el numero de columnas", "Asignar privilegios"], 1, "WHERE selecciona las filas que cumplen una condicion antes de GROUP BY. HAVING se usa para filtrar grupos despues de la agrupacion."),
    question("b3t4-practice-05", "joins-agrupaciones-y-vistas", "Un INNER JOIN devuelve:", ["Solo las filas que tienen coincidencia segun la condicion de union", "Todas las filas de ambas tablas aunque no haya coincidencia", "Unicamente filas nulas", "Una copia permanente de las dos tablas"], 0, "INNER JOIN conserva las combinaciones que satisfacen la condicion de union. Los LEFT/RIGHT/FULL OUTER JOIN pueden conservar filas sin correspondencia."),
    question("b3t4-practice-06", "joins-agrupaciones-y-vistas", "Que clausula permite filtrar grupos obtenidos tras un GROUP BY?", ["WHERE", "HAVING", "DISTINCT", "UNION"], 1, "HAVING aplica condiciones sobre los grupos, por ejemplo HAVING COUNT(*) > 1. WHERE actua sobre filas antes de formar los grupos."),
    question("b3t4-practice-07", "procedimientos-eventos-y-disparadores", "Un trigger o disparador es:", ["Una sentencia que se ejecuta automaticamente al producirse un evento definido sobre una tabla o vista", "Una copia manual de una base de datos", "Una conexion ODBC", "Una clave candidata"], 0, "Un trigger se activa ante eventos como INSERT, UPDATE o DELETE y puede ejecutar acciones asociadas, por ejemplo para auditoria o validaciones."),
    question("b3t4-practice-08", "procedimientos-eventos-y-disparadores", "La diferencia esencial entre un procedimiento almacenado y una funcion SQL es que, de forma habitual:", ["Un procedimiento no puede tener parametros", "Una funcion se invoca para devolver un valor y un procedimiento se ejecuta como una rutina", "Una funcion no puede contener sentencias SQL", "Un procedimiento siempre se ejecuta por un trigger"], 1, "Aunque hay diferencias por SGBD, normalmente las funciones se orientan a devolver un valor y los procedimientos a ejecutar una secuencia de operaciones invocable explicitamente."),
    question("b3t4-practice-09", "conectividad-y-casos-practicos", "ODBC es una interfaz orientada principalmente a:", ["Conectar aplicaciones con distintos SGBD mediante una API comun", "Crear diagramas entidad-relacion", "Definir claves primarias", "Sustituir el lenguaje SQL"], 0, "Open Database Connectivity proporciona una interfaz estandar para que aplicaciones, especialmente en entornos Windows, accedan a distintos controladores de bases de datos."),
    question("b3t4-practice-10", "conectividad-y-casos-practicos", "JDBC se emplea habitualmente para acceder a bases de datos desde aplicaciones:", ["Java", "COBOL exclusivamente", "HTML sin servidor", "Sistemas de ficheros locales sin SGBD"], 0, "Java Database Connectivity es la API estandar de Java para conectar aplicaciones Java con bases de datos mediante controladores JDBC."),
  ],
